import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ storage: multer.memoryStorage() });
const router = express.Router();

interface MatchResult {
  matchScore: number;
  foundKeywords: string[];
  missingKeywords: string[];
}

function analyzeResume(resumeText: string, jobKeywords: string[]): MatchResult {
  const normalizedText = resumeText.toLowerCase();
  const foundKeywords: string[] = [];
  const missingKeywords: string[] = [];

  jobKeywords.forEach((keyword) => {
    if (normalizedText.includes(keyword.toLowerCase())) {
      foundKeywords.push(keyword);
    } else {
      missingKeywords.push(keyword);
    }
  });

  const matchScore = jobKeywords.length > 0 
    ? Math.round((foundKeywords.length / jobKeywords.length) * 100) 
    : 0;

  return { matchScore, foundKeywords, missingKeywords };
}

router.post('/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume file uploaded.' });
      return;
    }

    const { keywords } = req.body;
    const parsedKeywords: string[] = keywords ? JSON.parse(keywords) : [];

    const pdfData = await pdfParse(req.file.buffer);
    const analysis = analyzeResume(pdfData.text, parsedKeywords);

    res.json({
      success: true,
      fileName: req.file.originalname,
      pageCount: pdfData.numpages,
      ...analysis,
    });
  } catch (error: any) {
    res.status(500).json({ success: false, error: error.message || 'Failed to parse PDF' });
  }
});

export default router;

import React, { useEffect, useState } from 'react';

interface ScanResultProps {
  matchScore: number;
  foundKeywords: string[];
  missingKeywords: string[];
}

export const AnimatedMatchScoreGauge: React.FC<ScanResultProps> = ({
  matchScore,
  foundKeywords,
  missingKeywords,
}) => {
  const [animatedScore, setAnimatedScore] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => {
      setAnimatedScore(matchScore);
    }, 100);
    return () => clearTimeout(timer);
  }, [matchScore]);

  const radius = 60;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (animatedScore / 100) * circumference;

  return (
    <div className="bg-white p-6 rounded-2xl shadow-lg border border-slate-100 flex flex-col md:flex-row items-center gap-8">
      <div className="relative flex items-center justify-center">
        <svg className="w-36 h-36 transform -rotate-90">
          <circle
            cx="72"
            cy="72"
            r={radius}
            stroke="#e2e8f0"
            strokeWidth="12"
            fill="transparent"
          />
          <circle
            cx="72"
            cy="72"
            r={radius}
            stroke="#4f46e5"
            strokeWidth="12"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            fill="transparent"
            className="transition-all duration-1000 ease-out"
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className="text-3xl font-extrabold text-slate-800">{animatedScore}%</span>
          <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Match Score</span>
        </div>
      </div>

      <div className="flex-1 space-y-4 w-full">
        <div>
          <h4 className="text-sm font-semibold text-emerald-600 mb-2">Found Keywords ({foundKeywords.length})</h4>
          <div className="flex flex-wrap gap-2">
            {foundKeywords.map((kw, idx) => (
              <span key={idx} className="px-3 py-1 bg-emerald-50 text-emerald-700 text-xs font-medium rounded-full border border-emerald-200">
                ✓ {kw}
              </span>
            ))}
          </div>
        </div>

        <div>
          <h4 className="text-sm font-semibold text-rose-600 mb-2">Missing Keywords ({missingKeywords.length})</h4>
          <div className="flex flex-wrap gap-2">
            {missingKeywords.map((kw, idx) => (
              <span key={idx} className="px-3 py-1 bg-rose-50 text-rose-700 text-xs font-medium rounded-full border border-rose-200">
                ✗ {kw}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};
